import type { SupabaseClient } from "@supabase/supabase-js";

export async function saveReminder(
  supabase: SupabaseClient,
  userId: string,
  plantId: string,
  everyDays: number,
) {
  await supabase
    .from("watering_reminders")
    .upsert({ user_id: userId, plant_id: plantId, every_days: everyDays });
  return { ok: true };
}
